<script setup>
import {ref} from 'vue';import {Head,Link,router,useForm} from '@inertiajs/vue3';
const props=defineProps({reports:Object,status:String,history:Object}),editing=ref(null),form=useForm({status:'resolved',resolution:'',revision:0});
function review(r){editing.value=r.id;form.status=r.status==='open'?'resolved':r.status;form.resolution=r.resolution||'';form.revision=r.revision}
</script>
<template><Head title="Question feedback"/><h1>Chef's Review</h1><p>Review the reported version, edit the question if needed, then record your response.</p><Link href="/admin">← Head Chef</Link><label class="spaced">Report status<select :value="status" @change="router.get('/admin/reports',{status:$event.target.value})"><option value="open">Open</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option><option value="all">All reports</option></select></label>
<p v-if="!reports.data.length" class="notice">No reports in this view.</p>
<article v-for="r in reports.data" :key="r.id" class="panel"><h2>{{r.question_id}} · {{r.category}}</h2><p>{{r.user.username}} · {{r.status}} · reported version {{r.version.version}}</p><p class="pre">{{r.details}}</p><details><summary>Reported question and answer</summary><p class="pre">{{r.version.content.stem}}</p><p>Answer {{r.version.content.key}}</p><p>{{r.version.content.rationale}}</p></details><div class="row spaced"><Link :href="'/admin/questions?search='+encodeURIComponent(r.question_id)">Edit current question</Link><button @click="review(r)">Record review</button></div>
<form v-if="editing===r.id" @submit.prevent="form.patch('/admin/reports/'+r.id,{preserveScroll:true,onSuccess:()=>editing=null})"><label>Decision<select v-model="form.status"><option value="resolved">Resolved</option><option value="dismissed">Dismissed with explanation</option><option value="open">Keep open</option></select></label><label>Response to learner<textarea v-model="form.resolution" required minlength="5" maxlength="3000" rows="3"></textarea></label><button class="primary" :disabled="form.processing">Save review and notify learner</button></form><details v-if="history[r.id]?.length"><summary>Review history</summary><p v-for="h in history[r.id]" :key="h.id">{{h.status}} · {{h.created_at}} · {{h.resolution}}</p></details></article>
<div class="row"><Link v-if="reports.prev_page_url" :href="reports.prev_page_url">Previous</Link><span>Page {{reports.current_page}} / {{reports.last_page}}</span><Link v-if="reports.next_page_url" :href="reports.next_page_url">Next</Link></div></template>
